<template><view v-if="visible && popup" class="popup-mask" @click.self="close"><view class="popup-card" :style="{ backgroundColor: popup.backgroundColor || '#FFFFFF' }"><image v-if="popup.image" class="popup-image" :src="popup.image" mode="aspectFill" /><view class="popup-content"><text class="popup-title">{{ popup.title }}</text><text v-if="popup.subtitle" class="popup-subtitle">{{ popup.subtitle }}</text><template v-if="popup.type === 'COUPON'"><view class="popup-amount"><text>¥</text><strong>{{ amount }}</strong></view><text class="popup-condition">满{{ threshold }}元可用</text><text v-if="popup.scopeText" class="popup-meta">{{ popup.scopeText }}</text><text v-if="popup.limitText" class="popup-meta">{{ popup.limitText }}</text></template><button class="popup-button" :loading="claiming" @click="action">{{ popup.buttonText }}</button></view></view><view v-if="popup.closeable" class="popup-close pressable" role="button" aria-label="关闭营销弹窗" @click="close"><uni-icons type="closeempty" size="30" color="#ffffff" /></view></view></template>
<script setup>import { computed, ref } from 'vue'; const props = defineProps({ visible: Boolean, popup: { type: Object, default: null } }); const emit = defineEmits(['close', 'claim', 'navigate']); const claiming = ref(false); const amount = computed(() => ((props.popup?.amountCents || 0) / 100).toFixed(0)); const threshold = computed(() => ((props.popup?.thresholdCents || 0) / 100).toFixed(0)); function close() { emit('close') } /* 展示组件不自行判定活动资格；优惠券领取必须等待 Store 获得云函数成功结果。 */ async function action() { if (props.popup?.type === 'COUPON') { claiming.value = true; try { await emit('claim') } finally { claiming.value = false } } else emit('navigate', props.popup) }</script>
<style scoped lang="scss">.popup-mask{position:fixed;z-index:200;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:48rpx;background:rgba(8,13,12,.68)}.popup-card{width:min(610rpx,88vw);overflow:hidden;border-radius:14rpx;box-shadow:0 28rpx 70rpx rgba(0,0,0,.28)}.popup-image{width:100%;height:260rpx}.popup-content{display:flex;min-height:360rpx;flex-direction:column;align-items:center;justify-content:center;padding:42rpx 38rpx;color:#74440d;text-align:center}.popup-title{font-size:40rpx;font-weight:700}.popup-subtitle{margin-top:14rpx;font-size:25rpx}.popup-amount{display:flex;align-items:flex-end;margin-top:14rpx}.popup-amount text{padding-bottom:18rpx;font-size:30rpx}.popup-amount strong{font-size:112rpx;line-height:1}.popup-condition,.popup-meta{margin-top:8rpx;font-size:26rpx}.popup-meta{color:#805728;font-size:22rpx}.popup-button{width:100%;margin-top:28rpx;background:transparent;color:#e43a35;font-size:34rpx;font-weight:700}.popup-close{display:flex;width:68rpx;height:68rpx;align-items:center;justify-content:center;margin-top:44rpx;border:3rpx solid #fff;border-radius:50%}</style>
